<?php $isEdit=!empty($specialty);?><div class="panel form-panel"><form method="post" action="<?= $isEdit?url('/specialties/'.$specialty['id'].'/update'):url('/specialties') ?>" class="form-grid"><?= csrf_field() ?><div class="field field-full"><label>Nombre *</label><input name="name" value="<?= e(old('name',$specialty['name']??'')) ?>" required><?php if(error('name')):?><small class="error-text"><?= e(error('name')) ?></small><?php endif;?></div><div class="field field-full"><label>Descripción</label><textarea name="description" rows="4"><?= e(old('description',$specialty['description']??'')) ?></textarea></div><label class="switch-row field-full"><input type="checkbox" name="active" <?= (int)old('active',$specialty['active']??1)===1?'checked':'' ?>><span>Especialidad activa</span></label><div class="form-actions field-full"><a class="btn" href="<?= url('/specialties') ?>">Cancelar</a><button class="btn btn-primary">Guardar</button></div></form></div>
